<script>
(function(){
  var CYCLE=5*60*60*1000, KEY='ap_promo_v2';
  function getStart(){
    try{var t=parseInt(localStorage.getItem(KEY),10);if(t&&Date.now()-t<CYCLE)return t;}catch(e){}
    var n=Date.now();try{localStorage.setItem(KEY,n);}catch(e){}return n;
  }
  var start=getStart();
  function pad(n){return n<10?'0'+n:''+n;}
  function tick(){
    var el=Date.now()-start;
    if(el>=CYCLE){start=Date.now();try{localStorage.setItem(KEY,start);}catch(e){}el=0;}
    var rem=Math.floor((CYCLE-el)/1e3);
    var h=pad(Math.floor(rem/3600));
    var m=pad(Math.floor((rem%3600)/60));
    var s=pad(rem%60);
    document.querySelectorAll('.apbH').forEach(function(e){e.textContent=h;});
    document.querySelectorAll('.apbM').forEach(function(e){e.textContent=m;});
    document.querySelectorAll('.apbS').forEach(function(e){e.textContent=s;});
  }
  tick();setInterval(tick,1000);
})();
</script>

