<script>
(function () {

  window.apxPick = function (card) {
    var val   = card.getAttribute('data-fmt');
    var label = card.getAttribute('data-label') || val;
    document.querySelectorAll('.apx-card').forEach(function (c) {
      c.classList.remove('apx-on');
      c.setAttribute('aria-checked', 'false');
    });
    card.classList.add('apx-on');
    card.setAttribute('aria-checked', 'true');
    var lv = document.getElementById('apx-lv');
    if (lv) lv.textContent = label;
    apxSync(val);
  };

  function apxSync(val) {
    /* Toutes les variantes utilisent désormais les valeurs exactes :
       "Digital" | "Poster A3" | "Displate" | "Displate avec cadre"
       On tente la valeur exacte en premier, puis les anciens noms en fallback
       pour compatibilité avec d'éventuels produits non migrés. */
    var attempts = [val];
    if (val === 'Displate')            attempts.push('Cadre Displate');
    if (val === 'Displate avec cadre') attempts.push('Cadre Displate avec Cadre', 'Cadre Displate + Cadre');
    if (val === 'Cadre Displate')      attempts.push('Displate');

    for (var ai = 0; ai < attempts.length; ai++) {
      var v = attempts[ai];
      var btn = document.querySelector(
        '[data-value="' + v + '"]:not(#apx-fmt *)'
      );
      if (btn) { btn.click(); return; }
    }

    /* Radios */
    document.querySelectorAll('input[type="radio"]').forEach(function (r) {
      if (r.closest('#apx-fmt')) return;
      for (var ai = 0; ai < attempts.length; ai++) {
        if (r.value === attempts[ai]) {
          r.checked = true; r.click();
          r.dispatchEvent(new Event('change', { bubbles: true }));
          return;
        }
      }
    });

    /* Selects */
    document.querySelectorAll('select').forEach(function (s) {
      if (s.closest('#apx-fmt')) return;
      Array.prototype.forEach.call(s.options, function (o) {
        for (var ai = 0; ai < attempts.length; ai++) {
          if (o.text.trim() === attempts[ai] || o.value === attempts[ai]) {
            s.value = o.value;
            s.dispatchEvent(new Event('change', { bubbles: true }));
          }
        }
      });
    });

    /* Labels / buttons texte */
    document.querySelectorAll('label, button').forEach(function (el) {
      if (el.closest('#apx-fmt')) return;
      for (var ai = 0; ai < attempts.length; ai++) {
        if (el.textContent.trim() === attempts[ai]) { el.click(); return; }
      }
    });
  }

  function findAndHide() {
    var found = false;

    /* Stratégie 1 : attribut data-option-index (Kalles / Dawn / etc.) */
    var opt1 = document.querySelector('[data-option-index="1"]');
    if (opt1 && !opt1.closest('#apx-fmt')) {
      opt1.classList.add('apx-version-hidden');
      return true;
    }

    /* Stratégie 2 : "Displate" est invariant dans toutes les langues,
       "A3" aussi (format papier). On remonte depuis un bouton Displate
       jusqu'au conteneur qui regroupe toutes les options Version. */
    var candidates = document.querySelectorAll('label, button, span, div, li');
    for (var i = 0; i < candidates.length; i++) {
      var el = candidates[i];
      if (el.closest('#apx-fmt')) continue;
      var t = el.textContent.trim();
      /* Cible les éléments dont le texte commence par "Displate"
         (couvre "Displate", "Displate-Rahmen", "Displate avec cadre"…) */
      if (t.indexOf('Displate') !== 0) continue;
      var node = el.parentElement, limit = 0;
      while (node && node !== document.body && limit < 12) {
        if (node.closest('#apx-fmt')) break;
        var nt = node.textContent || '';
        /* Le bloc natif contient "Displate" ET "A3" → c'est le sélecteur Version */
        if (nt.indexOf('Displate') > -1 && nt.indexOf('A3') > -1) {
          node.classList.add('apx-version-hidden');
          found = true; break;
        }
        node = node.parentElement; limit++;
      }
      if (found) break;
    }
    return found;
  }

  function init() {
    var ok = findAndHide();
    if (!ok && typeof MutationObserver !== 'undefined') {
      var obs = new MutationObserver(function () { if (findAndHide()) obs.disconnect(); });
      obs.observe(document.body, { childList: true, subtree: true });
      setTimeout(function () { obs.disconnect(); }, 5000);
    }
    var def = document.querySelector('.apx-card[data-fmt="Digital"]');
    if (def) apxPick(def);
  }

  if (document.readyState === 'loading') { document.addEventListener('DOMContentLoaded', init); }
  else { setTimeout(init, 180); }

})();
</script>

