@import url('https://fonts.googleapis.com/css2?family=Bebas+Neue&family=DM+Sans:wght@300;400;500&display=swap');
.apx-guar{margin:12px 0;padding:20px;background:#141416;border:1px solid rgba(255,255,255,.07);border-radius:18px;font-family:'DM Sans',sans-serif;}
.apx-guar__head{margin-bottom:16px;}
.apx-guar__badge{display:inline-flex;background:rgba(245,166,35,.08);border:1px solid rgba(245,166,35,.2);color:#f5a623;font-size:10px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;padding:3px 10px;border-radius:99px;margin-bottom:8px;}
.apx-guar__title{font-family:'Bebas Neue',sans-serif;font-size:20px;letter-spacing:.02em;color:#f0ede8;line-height:1.1;}
.apx-guar__grid{display:grid;grid-template-columns:repeat(2,1fr);gap:8px;list-style:none;padding:0;margin:0;align-items:stretch;}
.apx-guar__item{display:flex;align-items:center;gap:12px;padding:12px 14px;background:rgba(255,255,255,.03);border:1px solid rgba(255,255,255,.06);border-radius:12px;min-height:62px;}
.apx-guar__ico{width:36px;height:36px;border-radius:10px;display:flex;align-items:center;justify-content:center;flex-shrink:0;}
.apx-guar__ico--star{background:rgba(245,166,35,.12);color:#f5a623;border:1px solid rgba(245,166,35,.2);}
.apx-guar__ico--clock{background:rgba(99,179,237,.1);color:#63b3ed;border:1px solid rgba(99,179,237,.2);}
.apx-guar__ico--edit{background:rgba(154,214,117,.1);color:#9ad675;border:1px solid rgba(154,214,117,.2);}
.apx-guar__ico--brick{background:rgba(236,107,174,.1);color:#ec6bae;border:1px solid rgba(236,107,174,.2);}
.apx-guar__ico--lock{background:rgba(169,140,245,.1);color:#a98cf5;border:1px solid rgba(169,140,245,.2);}
.apx-guar__txt{flex:1;min-width:0;}
.apx-guar__top{font-size:12px;font-weight:600;color:#f0ede8;line-height:1.3;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.apx-guar__bot{font-size:11px;font-weight:300;color:#9a9690;margin-top:2px;line-height:1.3;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.apx-guar__item:last-child:nth-child(odd){grid-column:1/-1;}
.apx-guar__item:last-child:nth-child(odd) .apx-guar__top,.apx-guar__item:last-child:nth-child(odd) .apx-guar__bot{white-space:normal;}
@media(max-width:560px){.apx-guar__grid{grid-template-columns:1fr;}.apx-guar__item:last-child:nth-child(odd){grid-column:auto;}.apx-guar__top,.apx-guar__bot{white-space:normal;}}
</style>

