<section class="apx-faq-lego">
  <div class="apx-faq-lego__inner">
    <h2 class="apx-faq-lego__title">{{ faq_title }}</h2>

    {%- capture all_q -%}{{ q1 }}|||{{ q2 }}|||{{ q3 }}|||{{ q4 }}|||{{ q5 }}|||{{ q6 }}|||{{ q7 }}|||{{ q8 }}{%- endcapture -%}
    {%- capture all_a -%}{{ a1 }}|||{{ a2 }}|||{{ a3 }}|||{{ a4 }}|||{{ a5 }}|||{{ a6 }}|||{{ a7 }}|||{{ a8 }}{%- endcapture -%}
    {%- assign questions = all_q | split: '|||' -%}
    {%- assign answers = all_a | split: '|||' -%}

    {%- for question in questions -%}
      {%- assign answer = answers[forloop.index0] -%}
      <div class="apx-faq-lego__row">
        <details>
          <summary>
            <h3>{{ question | strip }}</h3>
            <span class="ap-arr" aria-hidden="true">+</span>
          </summary>
          <div class="apx-faq-lego__body"><p>{{ answer | strip }}</p></div>
        </details>
      </div>
    {%- endfor -%}

    <div class="apx-faq-lego__cta-wrap">
      <a href="/products/portrait-cartoon-personnalise-lego" class="ap-faq-cta">{{ cta_text }}</a>
    </div>
  </div>
</section>

